"""Minimal purchase alternative cards, presenting only existing calculated results."""
CSS='''
.po-alternatives-table{margin:16px 0;padding:18px;background:#f7faff;border:1px solid #d4dfed;border-radius:10px;color:#183454;min-width:0}.po-alternatives-table h3{font-size:16px!important;margin:0 0 14px}.po-alternatives-table p{font-size:13px;line-height:1.5}.po-alt-baseline{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;padding:12px 0 16px;border-bottom:1px solid #d6e0ec;margin-bottom:16px}.po-alt-baseline strong{font-size:22px}.po-alt-baseline span{font-size:13px}.po-alt-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,245px),1fr));gap:14px}.po-alt-card{background:white;border:1px solid #d6e0ec;border-radius:10px;padding:16px;min-width:0;overflow-wrap:anywhere}.po-alt-card header{min-height:44px;display:flex;justify-content:space-between;align-items:start;gap:8px}.po-alt-card h4{font-size:16px;margin:0;line-height:1.4}.po-alt-ref{font-size:11px;color:#60748c;white-space:nowrap}.po-alt-quantity{min-height:20px;font-size:13px;color:#536b85;margin:6px 0 14px!important}.po-alt-total{font-size:26px;font-weight:750;letter-spacing:-.02em;line-height:1.2}.po-alt-total small{font-size:12px;font-weight:400;display:block;margin-top:5px;color:#536b85}.po-alt-difference{min-height:40px;font-size:14px;margin:14px 0}.po-alt-difference[data-tone=green]{color:#21683b}.po-alt-difference[data-tone=red]{color:#9c3028}.po-alt-cash{display:inline-block;padding:5px 9px;border-radius:5px;font-size:12px;font-weight:650;background:#edf2f8}.po-alt-cash::before{content:'●';margin-right:6px}.po-alt-cash[data-tone=green]{color:#21683b;background:#edf7ef}.po-alt-cash[data-tone=red]{color:#9c3028;background:#fff0ed}.po-alt-card>details{margin:14px 0 0!important;border-top:1px solid #edf1f7;padding-top:12px}.po-alt-card summary,.po-alt-methods>summary{cursor:pointer;font-size:13px;font-weight:650}.po-alt-card details p{margin:9px 0}.po-alt-card pre{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}.po-alt-card button{width:100%;margin:14px 0 0!important;padding:9px!important;font-size:13px}.po-alt-methods{margin-top:18px;border-top:1px solid #d6e0ec;padding-top:12px}.po-alt-caption{color:#536b85;margin:12px 0 0!important;font-size:12px!important}.po-alt-card dl{margin:10px 0}.po-alt-card dl div{display:flex;justify-content:space-between;gap:10px;margin:8px 0;font-size:13px}.po-alt-card dd{margin:0;text-align:right;font-weight:600}.po-alt-card dt{color:#536b85}
'''
JS=r'''
(function purchaseAlternativesTable(){
 const live=document.createElement('section');live.id='po-alternatives-table';live.className='po-alternatives-table';live.setAttribute('aria-label','Comparación de alternativas calculadas');$('po-conditions').querySelector('.po-negotiation-scroll').after(live);
 const names={PRICE:'Bajar el precio',QUANTITY:'Comprar menos',DEFER:'Pagar más tarde',HISTORICAL_PRICE:'Precio de la última compra',STOCK_TARGET:'Ajustar la cantidad',COLLECTION_ALIGNED_PAYMENT:'Pagar después de un cobro',COMBINED:'Combinar condiciones'};
 function note(box,text){const p=document.createElement('p');p.textContent=text;box.append(p);return p}
 function render(box,r,editable){box.replaceChildren();const h=document.createElement('h3');h.textContent=editable?'OPCIONES PARA ESTA COMPRA':'OPCIONES DEL ESTUDIO GUARDADO';box.append(h);
 if(!r?.scenario||!r.current_terms||!r.analysis_fingerprint){note(box,!editable&&!r?.current_terms?'Este estudio anterior no conserva alternativas detalladas. Consulta sus resultados guardados.':r?.message||'Completa las condiciones para calcular opciones.');return}
 const base=r.current_terms,baseline=document.createElement('div');baseline.className='po-alt-baseline';baseline.dataset.baseline='true';const label=document.createElement('span'),price=document.createElement('strong'),qty=document.createElement('span');label.textContent='Propuesta de referencia';price.textContent=money(base.total)+' EUR';qty.textContent=stockNumber(base.quantity)+' '+base.unit;baseline.append(label,price,qty);box.append(baseline);
 const grid=document.createElement('div');grid.className='po-alt-cards';
 for(const a of r.alternatives||[]){const card=document.createElement('article');card.className='po-alt-card';card.dataset.alternativeKind=a.kind;const head=document.createElement('header'),title=document.createElement('h4'),ref=document.createElement('span');title.textContent=names[a.kind]||a.title;ref.className='po-alt-ref';ref.textContent=a.comparison_id||'Alternativa';head.append(title,ref);card.append(head);
 const same=Number(a.quantity)===Number(base.quantity);const quantity=note(card,stockNumber(a.quantity)+' '+(a.unit||base.unit)+(same?' · misma cantidad':' · cambia la cantidad'));quantity.className='po-alt-quantity';
 const total=document.createElement('div');total.className='po-alt-total';total.textContent=money(a.total)+' EUR';const tax=document.createElement('small');tax.textContent='Total con IVA y portes';total.append(tax);card.append(total);
 const saving=Number(a.savings),delta=note(card,(saving>=0?money(a.savings)+' EUR menos':money(-saving)+' EUR más')+(same?' que la referencia':' de desembolso · otra cantidad'));delta.className='po-alt-difference';delta.dataset.tone=saving<0?'red':'green';
 const okay=Number(a.minimum_balance)>=Number(r.treasury_minimum),cash=document.createElement('span');cash.className='po-alt-cash';cash.dataset.tone=okay?'green':'red';cash.textContent=okay?'Mantiene el colchón previsto':'No mantiene el colchón previsto';card.append(cash);
 if(editable){const button=document.createElement('button');button.type='button';button.textContent='Usar en Mi propuesta';button.onclick=()=>{if(typeof applyPurchaseSuggestedAlternative==='function')applyPurchaseSuggestedAlternative(a)};card.append(button)}
 const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Ver detalle';details.append(summary);note(details,a.title);const values=document.createElement('dl');for(const [key,value] of [['Precio neto por unidad',money(a.net_unit_price)+' EUR'],['Dinero mínimo previsto',money(a.minimum_balance)+' EUR'],['Fecha del mínimo',stockDate(a.minimum_date)],['Vencimiento mercancía',stockDate(a.due_date)]]){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=key;dd.textContent=value;row.append(dt,dd);values.append(row)}details.append(values);
 note(details,a.basis||'Hipótesis para negociar.');if(!same)note(details,'La diferencia incluye el cambio de cantidad: no equivale a ahorrar comprando el mismo volumen.');
 for(const payment of a.payments||[])note(details,'Pago: '+stockDate(payment.due_date)+' · '+money(payment.amount)+' EUR');
 const stress=a.collection_sensitivity;note(details,'Sin el mayor cobro previsto: '+(stress?(stress.reserve_respected?'respeta la reserva.':'faltan '+money(stress.deficit)+' EUR para la reserva.'):'sin prueba aplicable.'));
 const comparison=a.metric_comparison;if(comparison)note(details,comparison.dominated_by?.length?'A igual cantidad, otra opción mejora coste o caja sin empeorar la otra: '+comparison.dominated_by.join(', ')+'.':'A igual cantidad, no se ha encontrado otra opción que mejore coste o caja sin empeorar la otra.');
 if(a.source){const source=document.createElement('details'),s=document.createElement('summary'),pre=document.createElement('pre');s.textContent='Fuentes del cálculo';pre.textContent=JSON.stringify(a.source,null,2);source.append(s,pre);details.append(source)}note(details,'Pendiente de acuerdo con el proveedor. No confirma una compra.');card.append(details);grid.append(card)}box.append(grid);
 if(!r.alternatives?.length)note(box,'No hay otras opciones calculadas con los datos actuales.');
 const caption=note(box,'Opciones de prueba · Ninguna se selecciona automáticamente.');caption.className='po-alt-caption';
 const methods=document.createElement('details'),summary=document.createElement('summary');methods.className='po-alt-methods';summary.textContent='Saber más · criterios y comprobaciones';methods.append(summary);
 note(methods,'Importes con IVA y portes. Las diferencias se comparan con la propuesta de referencia. La comparación de coste y caja solo enfrenta cantidades iguales; no evalúa calidad ni fiabilidad del proveedor.');
 note(methods,'Referencia: precio neto '+money(base.net_unit_price)+' EUR por unidad; saldo mínimo '+money(base.minimum_balance)+' EUR el '+stockDate(base.minimum_date)+'; vencimiento '+stockDate(base.due_date)+'.');for(const payment of base.payments||[])note(methods,'Pago de referencia: '+stockDate(payment.due_date)+' · '+money(payment.amount)+' EUR');
 if(base.collection_sensitivity)note(methods,'Referencia sin el mayor cobro previsto: '+(base.collection_sensitivity.reserve_respected?'respeta la reserva.':'faltan '+money(base.collection_sensitivity.deficit)+' EUR para la reserva.'));
 if(base.metric_comparison?.dominated_by?.length)note(methods,'A igual cantidad, opciones que mejoran coste o caja de la referencia sin empeorar la otra: '+base.metric_comparison.dominated_by.join(', '));
 if(r.collection_sensitivity){note(methods,r.collection_sensitivity.message);const excluded=r.collection_sensitivity.excluded_collection;if(excluded)note(methods,'Cobro retirado solo en esta prueba: '+excluded.flow_id+' · '+money(excluded.amount)+' EUR · '+stockDate(excluded.due_date));}
 if(r.combination_analysis){const report=r.combination_analysis;note(methods,'Búsqueda combinada: '+report.evaluated+' combinaciones comprobadas · '+report.retained+' alternativas conservadas.');if(report.truncated)note(methods,'Búsqueda limitada a '+report.limit+' combinaciones; no es una exploración exhaustiva.');const counts=new Map();for(const rejected of report.rejected||[])counts.set(rejected.reason,(counts.get(rejected.reason)||0)+1);for(const [reason,count] of counts)note(methods,count+' descartes: '+reason);if(!report.evaluated)note(methods,'No hay al menos dos variables con alternativas sustentadas por fuentes para combinarlas.');}
 note(methods,'Aplicar prepara un borrador. Guardar conserva el estudio; no confirma un pedido.');note(methods,'Corte: '+stockDate(r.cutoff)+' · Horizonte: '+stockDate(r.horizon_end)+' · Huella: '+r.analysis_fingerprint);box.append(methods);
 }
 window.clearPurchaseAlternativesTable=()=>{live.replaceChildren();const h=document.createElement('h3');h.textContent='OPCIONES PARA ESTA COMPRA';live.append(h);note(live,'Recalculando…')};
 window.renderPurchaseAlternativesTable=r=>render(live,r,true);
 window.renderSavedPurchaseAlternativesTable=(parent,r)=>{const box=document.createElement('section');box.className='po-alternatives-table';render(box,r,false);parent.append(box)};
 clearPurchaseAlternativesTable();
})();
'''
